export async function exportProgressFile(text,deps={}){
 const nav=deps.navigator??globalThis.navigator,doc=deps.document??globalThis.document,urls=deps.URL??globalThis.URL,FileType=deps.File??globalThis.File,BlobType=deps.Blob??globalThis.Blob,later=deps.setTimeout??globalThis.setTimeout,name='batalha-das-urnas-progresso.json';
 if(FileType&&nav?.canShare&&nav?.share){
  let file,shareable=false;try{file=new FileType([text],name,{type:'application/json'});shareable=nav.canShare({files:[file]});}catch{}
  if(shareable){try{await nav.share({files:[file],title:'Progresso — Batalha das Urnas'});return 'shared';}catch(error){if(error?.name==='AbortError')return 'cancelled';}}
 }
 const url=urls.createObjectURL(new BlobType([text],{type:'application/json'})),a=doc.createElement('a');a.href=url;a.download=name;a.hidden=true;
 try{doc.body.append(a);a.click();}finally{a.remove();later(()=>urls.revokeObjectURL(url),10000);}return 'download';
}
const $=s=>document.querySelector(s), names={campaign:'Caminho ao Planalto',quick:'Batalha rápida',survival:'Sobrevivência',chaos:'Caos institucional',bossrush:'Desafio dos chefes'};
