 const s=this.progress.state,r=s.active[hero],route=CAMPAIGNS[hero];this.page(this.header('O caminho ao Planalto','TRÊS ATOS · DOZE ADVERSÁRIOS','campaign')+'<div class="campaign-top"><div class="hero-switch">'+['lula','flavio'].map(id=>'<button class="hero-pick '+(hero===id?'chosen':'')+'" data-hero="'+id+'">'+img(id)+'<b>'+C[id].name+'</b></button>').join('')+'</div><div class="campaign-brief"><span class="folio">DOSSIÊ / '+(hero==='lula'?'01':'02')+'</span><h3>Uma sessão de cada vez.</h3><p>Doze adversários. Três atos. Enfrente cada desafio e conquiste seu lugar no Planalto.</p><p>'+s.campaigns+' campanhas concluídas · nível '+this.progress.level(hero)+' · '+this.progress.points(hero)+' pontos para distribuir</p><label>Dificuldade <select id="campaignDifficulty">'+opts(difficulties,r?.difficulty||DEFAULT_DIFFICULTY)+'</select></label>'+ (isCampaignDifficultyLocked(r)?'<p class="campaign-lock-notice">'+CAMPAIGN_DIFFICULTY_LOCK_NOTICE+'</p>':campaignNeedsDifficultySelection(r)?'<p class="campaign-lock-notice">Evolução zerada. Escolha a dificuldade antes de começar a primeira batalha.</p>':'')+'<div class="action-row">'+(r?'<button id="continueCampaign" class="paint-button primary">'+(campaignNeedsDifficultySelection(r)?'COMEÇAR CAMPANHA':r.completed?(currentInternational(r)?'CONTINUAR DESAFIO INTERNACIONAL':'REVER ENCERRAMENTO'):'CONTINUAR · FASE '+(r.next+1))+'</button>':'')+'<button id="newCampaign" class="paint-button">'+(r&&!r.completed?'RECOMEÇAR CAMPANHA':'NOVA CAMPANHA')+'</button>'+(s.campaigns?'<button id="newPlus" class="paint-button">NOVO JOGO +</button>':'')+'</div></div></div><div class="route-list">'+ACTS.map((act,a)=>'<section><h3><i>0'+(a+1)+'</i> '+act+'</h3><div class="route-cards">'+route.filter(f=>f.act===a).map(f=>{const known=this.progress.isRevealed(hero,f.number);return '<article class="route-card '+(known?'revealed':'mystery')+' '+(f.kind!=='regular'?'boss':'')+' '+(r&&f.number<=r.next?'cleared':'')+'"><span class="stage-number">'+String(f.number).padStart(2,'0')+'</span><img src="'+C[f.opponent].portrait+'" alt="'+(known?'Caricatura de '+C[f.opponent].name:'Adversário ainda desconhecido')+'"><b>'+(known?C[f.opponent].name:'???')+'</b><small>'+SCENES.find(q=>q.id===f.scene).name+'</small><em>'+(f.kind==='final'?'CONFRONTO FINAL':f.kind==='miniboss'?'MINIBOSS':r&&f.number<=r.next?'CONCLUÍDA':'SESSÃO')+'</em>'+(known?'':'<span class="mystery-seal" aria-hidden="true">?</span>')+'</article>';}).join('')+'</div></section>').join('')+'</div><p class="save-note">'+(this.progress.available?'Progresso automático neste navegador. Exporte uma cópia em Controles & progresso.':'Armazenamento indisponível. Exporte uma cópia antes de fechar.')+'</p>');
