 campaignStage(run){if(!run)return false;if(campaignNeedsDifficultySelection(run))return this.campaign(run.hero);if(run.next>=12)return currentInternational(run)?this.internationalStage(run):this.finale(run);const phase=CAMPAIGNS[run.hero][run.next];this.session={kind:'campaign',hero:run.hero,characters:[run.hero,phase.opponent],scene:phase.scene,difficulty:run.difficulty,phase,runId:run.id,index:run.next,ng:run.ng,lives:phase.rules.lives,events:true,variant:'normal',normalized:false,roundId:run.checkpoint?.encounterId||uuid()};this.intro();}
